WITH lines AS (SELECT c.id, c.customer_id, c.created_at, c.coupon_codes, pos, line.product_id, line.qty, line.price, line.promo FROM carts c LATERAL VIEW POSEXPLODE(c.items) e AS pos, line) SELECT s.id, s.customer_id, s.created_at, s.coupon_codes, s.pos, s.product_id, s.qty, s.price, s.promo, (SELECT MIN(t2.discount) FROM orders t2 WHERE t2.customer_id = s.customer_id) AS min_order_discount FROM lines s ORDER BY pos DESC NULLS FIRST, product_id
